<?php
namespace App\Services\Instagram;
use App\Models\{InstagramPost,InstagramPublishQueue,InstagramPublishAttempt};
use App\Services\Automation\LockService;
use Illuminate\Support\Facades\Http;
use Illuminate\Support\Str;
class PublisherService {
 public function run():array { if(!config('berita.instagram_auto_publish'))return ['status'=>'disabled']; $lock=(new LockService)->acquire('instagram_publish',900); if(!$lock)return ['status'=>'locked']; try{$q=InstagramPublishQueue::where('status','READY')->where(fn($x)=>$x->whereNull('available_at')->orWhere('available_at','<=',now()))->orderByDesc('priority')->orderBy('id')->first(); if(!$q)return ['status'=>'empty'];$post=$q->post;if(!$post||$post->status!=='READY'){$q->update(['status'=>'SKIPPED']);return ['status'=>'skipped'];} if($post->media_id && InstagramPost::where('media_id',$post->media_id)->where('id','<>',$post->id)->exists())return ['status'=>'already_published','media_id'=>$post->media_id];$post->update(['status'=>'PROCESSING','last_attempt_at'=>now(),'attempt_count'=>$post->attempt_count+1]);$attempt=InstagramPublishAttempt::create(['instagram_post_id'=>$post->id,'instagram_publish_queue_id'=>$q->id,'status'=>'started','attempt_no'=>$post->attempt_count]);$started=microtime(true);try{$cfg=config('berita');$base='https://graph.instagram.com/'.($cfg['instagram_api_version']??'v26.0');$headers=['Authorization'=>'Bearer '.$cfg['instagram_access_token'],'Accept'=>'application/json'];$create=Http::withHeaders($headers)->asForm()->timeout(20)->post($base.'/'.$cfg['instagram_user_id'].'/media',['image_url'=>$post->image_url,'caption'=>$post->caption]);if(!$create->successful())throw $this->metaError($create);$container=$create->json('id');if(!$container)throw new \RuntimeException('container_id_missing');$post->update(['container_id'=>$container]);$ready=false;for($i=0;$i<5;$i++){usleep(300000);$status=Http::withHeaders($headers)->timeout(10)->get($base.'/'.$container.'?fields=status_code,status');$code=strtoupper((string)($status->json('status_code')??$status->json('status')??''));if(in_array($code,['FINISHED','READY','PUBLISHED'],true)){$ready=true;break;}if(in_array($code,['ERROR','EXPIRED'],true))throw new \RuntimeException('container_'.$code);}if(!$ready)throw new \RuntimeException('container_processing_timeout');$publish=Http::withHeaders($headers)->asForm()->timeout(15)->post($base.'/'.$cfg['instagram_user_id'].'/media_publish',['creation_id'=>$container]);if(!$publish->successful())throw $this->metaError($publish);$media=$publish->json('id');if(!$media)throw new \RuntimeException('media_id_missing');$post->update(['status'=>'PUBLISHED','media_id'=>$media,'published_at'=>now(),'last_error'=>null]);$q->update(['status'=>'PUBLISHED','published_at'=>now(),'locked_at'=>null]);$attempt->update(['status'=>'success','container_id'=>$container,'media_id'=>$media,'duration_ms'=>(int)((microtime(true)-$started)*1000)]);return ['status'=>'published','post_id'=>$post->id,'container_id'=>$container,'media_id'=>$media];}catch(\Throwable $e){$message=Str::limit($e->getMessage(),500);$ambiguous=$e->getCode()===408||str_contains(strtolower($message),'timeout')&&str_contains(strtolower($message),'publish');$attempt->update(['status'=>$ambiguous?'ambiguous':'failed','error'=>$message,'duration_ms'=>(int)((microtime(true)-$started)*1000)]);$post->update(['status'=>$ambiguous?'AMBIGUOUS':'READY','last_error'=>$message]);$q->update(['status'=>$ambiguous?'AMBIGUOUS':'READY','available_at'=>$ambiguous?null:now()->addSeconds((int)config('berita.instagram_throttle_seconds',300)),'last_error'=>$message]);return ['status'=>$ambiguous?'ambiguous':'failed','error'=>$message];}}finally{(new LockService)->release('instagram_publish',$lock);}}
 private function metaError($response):\Throwable { $message=$response->json('error.message')?:'instagram_http_'.$response->status();return new \RuntimeException(Str::limit(preg_replace('/Bearer\\s+\\S+/i','Bearer [redacted]',$message),300),$response->status()===408?408:$response->status()); }
}
